// Row 82c, item 3: the seed-time generator of the v2 demo packages (`../demo-seed`), on a
// throw-away data directory (`demo-seed-support.ts` says what is real).
//
// HERE the camera files are BUILT BOX BY BOX (row 82's `recordSession`: the worker's box shapes,
// generated bytes) and handed over by a synthesiser double, so that the file needs no helper
// program: generate -> verify clean PASS -> tamper -> verify names (VIDEO-02, 3). The same script
// with the REAL helper program and real H.264, and the measured sizes, is
// `demo-seed.generated.test.ts`. Evidence integrity: every verdict has its control.
import { createHash } from 'node:crypto';
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { PackageFile, declaredPackageFiles, parseManifestV2 } from '@dems/shared/evidence-package';
import { VERIFY_V2_CHECKS } from '@dems/shared/evidence-verify';
import { DEMO_TAMPERED_FRAGMENT_SEQ, DEMO_TAMPERED_FRAGMENT_TRACK } from '@dems/shared/sim';
import { afterAll, describe, expect, it } from 'vitest';
import { createCredentialStore } from '../../credential-store';
import { removePackages, throwAwaySigner } from '../../sealing/__tests__/package-support';
import { recordSession, removeRecordings } from '../../sealing/__tests__/pipeline-support';
import {
  DEMO_CAMERA_BITRATE_BPS,
  DEMO_CLIP_SECONDS,
  DEMO_MOVFLAGS,
  DEMO_PACKAGE_MAX_BYTES,
  DEMO_TAMPERED_FRAGMENT,
  DEMO_VIDEO_ENCODER,
  DemoSealError,
  DemoSourceArgumentError,
  demoCameraFileArguments,
  demoCameraFileBytesBound,
  isDemoTamperItem,
  sealDemoPackages,
  type DemoSealOptions,
} from '../demo-seed';
import { demoCore, demoItem, openerOver, removeDemoCores } from './demo-seed-support';

afterAll(() => {
  removeDemoCores();
  removeRecordings();
  removePackages();
});

const ALL = VERIFY_V2_CHECKS.map((check) => check.id);
const sha256 = (path: string): string => createHash('sha256').update(readFileSync(path)).digest('hex');
/** Every file below `dir`, `/`-joined, sorted. */
const tree = (dir: string, below = ''): string[] =>
  readdirSync(join(dir, below), { withFileTypes: true })
    .flatMap((entry) => (entry.isDirectory() ? tree(dir, join(below, entry.name)) : [join(below, entry.name)]))
    .sort();

/** The synthesiser double: a camera file of `fragments` whole fragments, in the worker's box shapes, copied to where the helper would write. */
function builtSynthesiser(fragments = 4): { readonly synthesise: DemoSealOptions['synthesise']; readonly calls: { trackId: string; args: readonly string[]; outPath: string }[] } {
  const calls: { trackId: string; args: readonly string[]; outPath: string }[] = [];
  let recording = recordSession({ fragments });
  return {
    calls,
    synthesise: async (request) => {
      calls.push({ ...request });
      if (request.trackId === 'VIDEO-01') recording = recordSession({ fragments });
      copyFileSync(recording.recordingFile(request.trackId), request.outPath);
    },
  };
}

const failureOf = async (run: Promise<unknown>): Promise<DemoSealError> => {
  try {
    await run;
  } catch (error) {
    if (error instanceof DemoSealError) return error;
    throw error;
  }
  throw new Error('the generator did not refuse');
};

describe('the generated camera file of a demo package: a pure argument table (row 82c)', () => {
  const args = demoCameraFileArguments({ seconds: DEMO_CLIP_SECONDS, outPath: '/data/media/sessions/SESSION-SES-20261009-0005/VIDEO-01.mp4' });

  it('a camera-realistic rate is EXPLICIT: bitrate, ceiling and buffer of the plan profile (4 Mbit/s), with the encoder of the development fake camera and the worker\'s fragment form', () => {
    expect(DEMO_CAMERA_BITRATE_BPS).toBe(4_000_000);
    expect(args.join(' ')).toContain('-b:v 4000000 -maxrate 4000000 -bufsize 4000000');
    // The encoder table of the generated source of the FAKE kind (`adapters/local/camera-helper-args.ts`, ENCODER.X264), without `-an`.
    expect([...DEMO_VIDEO_ENCODER]).toEqual(['-c:v', 'libx264', '-preset', 'ultrafast', '-tune', 'zerolatency', '-pix_fmt', 'yuv420p', '-g', '30', '-bf', '0', '-flags', '+global_header']);
    expect(args.join(' ')).toContain('testsrc2=size=1280x720:rate=30');
    expect(args.join(' ')).toContain(`-movflags ${DEMO_MOVFLAGS} -min_frag_duration 2000000 -f mp4`);
    expect(DEMO_MOVFLAGS).toBe('+frag_keyframe+empty_moov+default_base_moof+skip_trailer');
    expect(args.at(-1)).toBe('/data/media/sessions/SESSION-SES-20261009-0005/VIDEO-01.mp4');
    // No live input, no network output, no device.
    expect(args.join(' ')).not.toMatch(/avfoundation|rtsp|-re\b|udp:|tcp:/);
  });

  it('the size of a demo package follows from the rate: 8 s is about 4 MB per camera file, two files stay under the 10 MB bound', () => {
    expect(demoCameraFileBytesBound(DEMO_CLIP_SECONDS)).toBe(4_064_000);
    expect(2 * demoCameraFileBytesBound(DEMO_CLIP_SECONDS)).toBeLessThan(DEMO_PACKAGE_MAX_BYTES);
    // CONTROL: the rate of the generated source as row 86 measured it (about 25 MB per second) is not under it.
    expect(2 * 25_000_000 * DEMO_CLIP_SECONDS).toBeGreaterThan(DEMO_PACKAGE_MAX_BYTES);
  });

  it('refuses a clip length or a path that is not of its shape', () => {
    for (const seconds of [0, 1, 1.5, 31, Number.NaN]) expect(() => demoCameraFileArguments({ seconds, outPath: '/x/VIDEO-01.mp4' })).toThrow(DemoSourceArgumentError);
    for (const outPath of ['VIDEO-01.mp4', '/x/VIDEO-01.mov', '/x/a\0.mp4', '']) expect(() => demoCameraFileArguments({ seconds: 8, outPath })).toThrow(DemoSourceArgumentError);
  });

  it('the tamper demo is the item of evidence sequence 5, and its fragment is the shared constants\'', () => {
    expect(DEMO_TAMPERED_FRAGMENT).toEqual({ trackId: DEMO_TAMPERED_FRAGMENT_TRACK, seq: DEMO_TAMPERED_FRAGMENT_SEQ });
    expect(DEMO_TAMPERED_FRAGMENT).toEqual({ trackId: 'VIDEO-02', seq: 3 });
    expect(['EV-20261009-0005', 'EV-20270101-0005'].map(isDemoTamperItem)).toEqual([true, true]);
    expect(['EV-20261009-0004', 'EV-20261009-0015', 'EV-0005', 'x'].map(isDemoTamperItem)).toEqual([false, false, false, false]);
  });
});

describe('the seed-time generator: generate -> verify clean PASS -> tamper -> verify names (VIDEO-02, 3) (row 82c; ev §F.2)', () => {
  it('one clean item and EV 0005 are sealed by the PRODUCT pipeline into the Core\'s own store, read as development packages, and only EV 0005 is altered - on one fragment', async () => {
    const core = demoCore('script');
    const source = builtSynthesiser();
    const [clean, tampered] = await sealDemoPackages({ ...core.options(), synthesise: source.synthesise }, [demoItem(1), demoItem(5)]);
    if (clean === undefined || tampered === undefined) throw new Error('two items were asked');

    // Nothing recorded live: four files asked of the helper door, each with the argument table and its own path in the session folder.
    expect(source.calls.map((call) => [call.trackId, call.outPath])).toEqual([
      ['VIDEO-01', join(core.packageDir('SES-20261009-0001'), 'VIDEO-01.mp4')],
      ['VIDEO-02', join(core.packageDir('SES-20261009-0001'), 'VIDEO-02.mp4')],
      ['VIDEO-01', join(core.packageDir('SES-20261009-0005'), 'VIDEO-01.mp4')],
      ['VIDEO-02', join(core.packageDir('SES-20261009-0005'), 'VIDEO-02.mp4')],
    ]);
    for (const call of source.calls) expect(call.args).toEqual(demoCameraFileArguments({ seconds: DEMO_CLIP_SECONDS, outPath: call.outPath }));

    // THE CLEAN ITEM, judged by the verifier of operation 41 called HERE (not the generator's own word).
    const cleanVerdict = await core.verify(clean);
    expect(cleanVerdict.ok).toBe(true);
    expect(cleanVerdict.checks.filter((check) => check.status === 'PASS').map((check) => check.id)).toEqual(ALL);
    expect(clean.tampered).toBeNull();
    expect(clean.verify).toMatchObject({ ok: true, overall: 'PASS', failedChecks: [], fragments: [] });

    // EV 0005: TAMPERED, and the ONE fragment that does not verify is (VIDEO-02, 3); the chain breaks from it; manifest, signature and certificate pass.
    const verdict = await core.verify(tampered);
    expect({ ok: verdict.ok, overall: verdict.overall }).toEqual({ ok: false, overall: 'TAMPERED' });
    expect(verdict.fragments.map((fragment) => [fragment.trackId, fragment.seq, fragment.storedOk])).toEqual([['VIDEO-02', 3, false]]);
    expect(verdict.files.map((file) => [file.trackId, file.storedOk, file.chainBrokenFromSeq])).toEqual([
      ['VIDEO-01', true, null],
      ['VIDEO-02', false, 3],
    ]);
    const failed = verdict.checks.filter((check) => check.status === 'FAIL').map((check) => check.id);
    expect(failed).toEqual(['V-04', 'V-06', 'V-08']);
    for (const id of ['V-01', 'V-02', 'V-03', 'V-07', 'V-09', 'V-13', 'V-14', 'V-15']) expect(verdict.checks.find((check) => check.id === id)?.status).toBe('PASS');
    expect(verdict.checks.find((check) => check.id === 'V-04')?.findings.filter((finding) => finding.seq !== undefined).map((finding) => [finding.trackId, finding.seq])).toEqual([['VIDEO-02', 3]]);
    expect(tampered.tampered).toEqual({ trackId: 'VIDEO-02', seq: 3 });
    expect(tampered.verify).toMatchObject({ ok: false, overall: 'TAMPERED', failedChecks: failed, fragments: [{ trackId: 'VIDEO-02', seq: 3 }], chainBrokenFromSeq: 3 });

    // BOTH READ AS DEVELOPMENT PACKAGES: the manifest (fields 6, 7, 126), the verify report's sources and its development-key line, and the item's column.
    for (const [sealed, report] of [
      [clean, cleanVerdict],
      [tampered, verdict],
    ] as const) {
      const manifest = parseManifestV2(JSON.parse(readFileSync(join(core.packageDir(sealed.sessionId), PackageFile.MANIFEST), 'utf8')));
      expect({ integrity: manifest.integrity, demo: manifest.demo, developmentSources: manifest.developmentSources, simulated: manifest.signature.simulated }).toEqual({ integrity: 'DEMO_PACKAGE', demo: true, developmentSources: true, simulated: false });
      expect(manifest.tracks.map((track) => track.sourceClass)).toEqual(['FAKE', 'FAKE']);
      expect(manifest.device.certificate.subject).toContain('OU=DEVELOPMENT KEY - NOT FOR PRODUCTION');
      expect(report.sources).toMatchObject({ ok: true, code: 'DEVELOPMENT', development: true });
      expect(report.signature).toMatchObject({ ok: true, developmentKey: true, simulated: false });
      expect(sealed.seal.developmentSources).toBe(true);
      expect(sealed.verify).toMatchObject({ developmentSources: true, developmentKey: true });
      expect(sealed.fragmentsPerFile).toEqual([4, 4]);
      // The package folder is the package: no plaintext recording, nothing undeclared.
      expect(sealed.files).toEqual([...declaredPackageFiles({ transcript: false })].sort());
      expect(tree(core.packageDir(sealed.sessionId))).toEqual(sealed.files);
    }

    // THE SESSION KEYS ARE IN THE CREDENTIAL STORE OF THAT CORE, and nowhere else.
    expect(['KID-SES-20261009-0001', 'KID-SES-20261009-0005'].map((keyId) => core.store.sessionKeys.has(keyId))).toEqual([true, true]);
    const stranger = createCredentialStore({ root: join(demoCore('stranger').dataDir, 'credential-store') });
    const elsewhere = await core.verify(clean, openerOver(stranger));
    expect(elsewhere.ok).toBe(false);
    expect(elsewhere.checks.find((check) => check.id === 'V-05')?.findings.map((finding) => finding.code)).toContain('SESSION_KEY_UNAVAILABLE');

    // WHERE IT WROTE: the two session folders below the evidence store of the data directory; the staging folder is gone.
    expect(readdirSync(core.mediaStoreDir).sort()).toEqual(['.sealing', 'SESSION-SES-20261009-0001', 'SESSION-SES-20261009-0005']);
    expect(tree(join(core.mediaStoreDir, '.sealing'))).toEqual([]);
    expect(readdirSync(core.dataDir).sort()).toEqual(['credential-store', 'media', 'signer']);
    expect(core.log.entries.filter((entry) => entry.level !== 'warn')).toEqual([]);
  });

  it('CONTROL of the tamper: an item of another sequence under the same generator is left clean, byte for byte as sealed', async () => {
    const core = demoCore('control');
    const [fourth] = await sealDemoPackages({ ...core.options(), synthesise: builtSynthesiser().synthesise }, [demoItem(4)]);
    expect(fourth?.tampered).toBeNull();
    expect((await core.verify(fourth!)).ok).toBe(true);
  });

  it('exactly ONE byte of ONE file was altered after the seal: restoring that byte makes EV 0005 pass every check again', async () => {
    const core = demoCore('one-byte');
    const [tampered] = await sealDemoPackages({ ...core.options(), synthesise: builtSynthesiser().synthesise }, [demoItem(5)]);
    const manifest = parseManifestV2(JSON.parse(readFileSync(join(core.packageDir(tampered!.sessionId), PackageFile.MANIFEST), 'utf8')));
    const fragment = manifest.files.find((file) => file.trackId === 'VIDEO-02')!.fragments.find((entry) => entry.seq === 3)!;
    const path = join(core.packageDir(tampered!.sessionId), 'fragments', 'VIDEO-02.mp4');
    const bytes = readFileSync(path);
    const at = fragment.byteOffset + Math.floor(fragment.byteLength / 2);
    bytes[at] = bytes[at]! ^ 0xff;
    writeFileSync(path, bytes);
    const restored = await core.verify(tampered!);
    expect(restored.ok).toBe(true);
    expect(restored.checks.filter((check) => check.status === 'PASS').map((check) => check.id)).toEqual(ALL);
  });
});

describe('what the generator refuses, and what it leaves behind when it does (row 82c)', () => {
  it('a signing key that is not the development key: nothing is synthesised, nothing is written', async () => {
    const core = demoCore('key');
    const source = builtSynthesiser();
    const failure = await failureOf(sealDemoPackages({ ...core.options(), signing: throwAwaySigner(), synthesise: source.synthesise }, [demoItem(1)]));
    expect(failure.code).toBe('NOT_A_DEVELOPMENT_KEY');
    expect(source.calls).toEqual([]);
    expect(existsSync(core.mediaStoreDir)).toBe(false);
  });

  it('an evidence store outside the data directory (or the data directory itself): refused before anything is written', async () => {
    const core = demoCore('outside');
    const other = demoCore('elsewhere');
    const source = builtSynthesiser();
    for (const mediaStoreDir of [other.mediaStoreDir, core.dataDir, join(core.dataDir, '..', 'media')]) {
      expect((await failureOf(sealDemoPackages({ ...core.options(), mediaStoreDir, synthesise: source.synthesise }, [demoItem(1)]))).code).toBe('STORE_OUTSIDE_DATA_DIR');
    }
    expect(source.calls).toEqual([]);
    expect(existsSync(other.mediaStoreDir)).toBe(false);
  });

  it('a session folder that exists is never written into and never removed: a second call for the same item is refused, the sealed package is unchanged', async () => {
    const core = demoCore('exists');
    const [first] = await sealDemoPackages({ ...core.options(), synthesise: builtSynthesiser().synthesise }, [demoItem(1)]);
    const before = tree(core.packageDir(first!.sessionId)).map((name) => sha256(join(core.packageDir(first!.sessionId), name)));
    const source = builtSynthesiser();
    expect((await failureOf(sealDemoPackages({ ...core.options(), synthesise: source.synthesise }, [demoItem(1)]))).code).toBe('PACKAGE_EXISTS');
    expect(source.calls).toEqual([]);
    expect(tree(core.packageDir(first!.sessionId)).map((name) => sha256(join(core.packageDir(first!.sessionId), name)))).toEqual(before);
    // The same for a folder that is somebody else's and holds no package.
    mkdirSync(core.packageDir('SES-20261009-0002'), { recursive: true });
    writeFileSync(join(core.packageDir('SES-20261009-0002'), 'VIDEO-01.mp4'), 'a recording of a session');
    expect((await failureOf(sealDemoPackages({ ...core.options(), synthesise: source.synthesise }, [demoItem(2)]))).code).toBe('PACKAGE_EXISTS');
    expect(readFileSync(join(core.packageDir('SES-20261009-0002'), 'VIDEO-01.mp4'), 'utf8')).toBe('a recording of a session');
  });

  it('a clip too short to hold fragment 3: EV 0005 is NOT left as a clean-looking package - what the call created is removed, and the failure is in the persistent log', async () => {
    const core = demoCore('short');
    const failure = await failureOf(sealDemoPackages({ ...core.options(), synthesise: builtSynthesiser(2).synthesise }, [demoItem(5)]));
    expect(failure.code).toBe('TAMPER_FRAGMENT_ABSENT');
    expect(failure.detail).toEqual({ trackId: 'VIDEO-02', seq: 3 });
    expect(existsSync(core.packageDir('SES-20261009-0005'))).toBe(false);
    expect(core.log.entries.filter((entry) => entry.level === 'error').map((entry) => entry.code)).toEqual(['TAMPER_FRAGMENT_ABSENT']);
    // CONTROL: the same short clip seals a CLEAN item.
    const [clean] = await sealDemoPackages({ ...core.options(), synthesise: builtSynthesiser(2).synthesise }, [demoItem(1)]);
    expect(clean?.verify.ok).toBe(true);
  });

  it('a package above its size bound is removed, with the measured size in the failure; a helper that wrote nothing likewise', async () => {
    const core = demoCore('size');
    const tooLarge = await failureOf(sealDemoPackages({ ...core.options(), maxPackageBytes: 4_096, synthesise: builtSynthesiser().synthesise }, [demoItem(1)]));
    expect(tooLarge.code).toBe('PACKAGE_TOO_LARGE');
    expect(tooLarge.detail.limitBytes).toBe(4_096);
    expect(tooLarge.detail.bytes).toBeGreaterThan(4_096);
    expect(existsSync(core.packageDir('SES-20261009-0001'))).toBe(false);
    // A bound above 10 MB is not taken.
    const [sealed] = await sealDemoPackages({ ...core.options(), maxPackageBytes: Number.MAX_SAFE_INTEGER, synthesise: builtSynthesiser().synthesise }, [demoItem(1)]);
    expect(sealed!.bytes).toBeLessThan(DEMO_PACKAGE_MAX_BYTES);
    const silent = await failureOf(sealDemoPackages({ ...core.options(), synthesise: async () => {} }, [demoItem(3)]));
    expect(silent.code).toBe('SOURCE_NOT_SYNTHESISED');
    expect(existsSync(core.packageDir('SES-20261009-0003'))).toBe(false);
  });

  it('an item that is not of its shape, or named twice, is refused before anything is written', async () => {
    const core = demoCore('input');
    const source = builtSynthesiser();
    for (const items of [[{ ...demoItem(1), sessionId: '../SES-20261009-0001' }], [{ ...demoItem(1), evidenceId: 'EV-1' }], [demoItem(1), demoItem(1)], [{ ...demoItem(1), startedAt: 1.5 }]]) {
      expect((await failureOf(sealDemoPackages({ ...core.options(), synthesise: source.synthesise }, items))).code).toBe('INPUT_INVALID');
    }
    expect(source.calls).toEqual([]);
    expect(existsSync(core.mediaStoreDir)).toBe(false);
  });
});
